-- Hinge Health — Здоров'я та краса › Реабілітація та фізіотерапія
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hinge Health', NULL, 'https://www.hingehealth.com', NULL, NULL, 'Цифрова платформа реабілітації опорно-рухового апарату: комп''ютерний зір через камеру телефону стежить за технікою вправ для спини, коліна, стегна, шиї й плеча та дає зворотний зв''язок у реальному часі.', 'A digital musculoskeletal rehabilitation platform: computer vision through your phone camera tracks exercise form for the back, knee, hip, neck and shoulder and gives real-time feedback.', 'Hinge Health — одна з найбільших цифрових платформ реабілітації опорно-рухового апарату в США. Користувач отримує структуровану програму вправ під конкретну проблему — біль у спині, коліні, стегні, шиї чи плечі або відновлення після травми — і виконує її вдома. Технологія комп''ютерного зору через камеру телефону відстежує техніку виконання вправ і в реальному часі підказує, як виправити рух. Паралельно з пацієнтом дистанційно працює фізичний терапевт, а прогрес зберігається й відображається з часом. Сервіс часто надається безкоштовно через роботодавця чи медичну страховку; умови прямої підписки — за запитом. Платформа не замінює очну консультацію лікаря при гострому болю чи серйозній травмі.', 'Hinge Health is one of the largest digital musculoskeletal rehabilitation platforms in the US. Users get a structured exercise programme for a specific problem — back, knee, hip, neck or shoulder pain, or recovery after an injury — and follow it at home. Computer vision through the phone camera tracks exercise form and gives real-time cues on how to correct the movement. A physical therapist supports the patient remotely, and progress is saved and shown over time. The service is often provided free through an employer or health insurance; direct subscription terms are available on request. The platform does not replace an in-person doctor visit for acute pain or a serious injury.', 'Відстеження техніки вправ через камеру телефону
Структуровані програми під конкретну проблему (спина, коліно, плече)
Дистанційна підтримка фізичного терапевта
Відстеження прогресу з часом', 'Exercise form tracking through the phone camera
Structured programmes for a specific problem (back, knee, shoulder)
Remote support from a physical therapist
Progress tracking over time', 'Люди з болем у спині, суглобах чи після травми, які проходять реабілітацію вдома.', 'People with back or joint pain or recovering from an injury who do their rehabilitation at home.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-09-30 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hingehealth.com' OR LOWER(`name`) = LOWER('Hinge Health')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hingehealth.com' OR LOWER(`name`) = LOWER('Hinge Health')) ORDER BY `id` LIMIT 1);
