-- Rehab AI (AIMD) — Здоров'я та краса › Реабілітація та фізіотерапія
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Rehab AI (AIMD)', NULL, 'https://play.google.com/store/apps/details?id=global.aimd.rehabai', NULL, NULL, 'AI-асистент реабілітації з базою знань на основі доказової медицини: фізична, спортивна та неврологічна реабілітація для фахівців, студентів і пацієнтів.', 'An AI rehabilitation assistant with an evidence-based knowledge base covering physical, sports and neurological rehabilitation for professionals, students and patients.', 'Rehab AI від AIMD — мобільний AI-асистент для реабілітації, що спирається на базу знань доказової медицини. Він працює як довідник з реабілітаційних протоколів і має кілька спеціалізованих напрямків: фізична, спортивна та неврологічна реабілітація. Фахівцям — фізіотерапевтам, ерготерапевтам і лікарям — застосунок допомагає швидко знаходити обґрунтовані підходи та підтримує ухвалення рішень, студентам медичних спеціальностей слугує навчальним матеріалом, а пацієнтам дає змогу знайти перевірену інформацію про відновлення. Відповіді AI мають довідковий характер і не замінюють клінічне рішення фахівця. Умови використання й вартість — див. сторінку застосунку.', 'Rehab AI by AIMD is a mobile AI rehabilitation assistant built on an evidence-based medicine knowledge base. It works as a reference for rehabilitation protocols and has several specialised tracks: physical, sports and neurological rehabilitation. For professionals — physiotherapists, occupational therapists and doctors — the app helps find well-grounded approaches quickly and supports decision-making; for medical students it serves as learning material; and patients can use it to find reliable information about recovery. AI answers are for reference only and do not replace a clinician''s judgement. For terms of use and pricing, see the app page.', 'AI-довідник з реабілітаційних протоколів
Спеціалізовані напрямки: фізична, спортивна, неврологічна реабілітація
Підтримка рішень для фахівців
Освітні матеріали на основі доказової медицини', 'AI reference for rehabilitation protocols
Specialised tracks: physical, sports and neurological rehabilitation
Decision support for professionals
Evidence-based educational materials', 'Фізіотерапевти, ерготерапевти, лікарі, студенти медичних спеціальностей і пацієнти, які шукають перевірену інформацію про реабілітацію.', 'Physiotherapists, occupational therapists, doctors, medical students and patients looking for reliable rehabilitation information.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-09-30 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'play.google.com/store/apps/details?id=global.aimd.rehabai' OR LOWER(`name`) = LOWER('Rehab AI (AIMD)')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'play.google.com/store/apps/details?id=global.aimd.rehabai' OR LOWER(`name`) = LOWER('Rehab AI (AIMD)')) ORDER BY `id` LIMIT 1);
