-- PhysioAI (AI Posture Therapy) — Здоров'я та краса › Реабілітація та фізіотерапія
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PhysioAI (AI Posture Therapy)', NULL, 'https://apps.apple.com/us/app/ai-posture-therapy-physioai/id6756598601', NULL, NULL, 'Сканує поставу через камеру телефону й формує персональний план домашніх вправ для корекції; план можна експортувати в PDF для фахівця чи друку.', 'Scans your posture with the phone camera and builds a personal home exercise plan to correct it; the plan can be exported to PDF for a professional or for printing.', 'PhysioAI (AI Posture Therapy) — мобільний застосунок, який за допомогою штучного інтелекту сканує поставу й положення тіла через камеру телефону. За результатами сканування він підбирає персональні вправи для корекції та формує план домашніх тренувань із покроковими інструкціями. План можна експортувати у PDF, щоб роздрукувати, займатися офлайн або поділитися з фізіотерапевтом чи тренером. Повторні сканування допомагають бачити зміни з часом. Застосунок підходить для самостійної роботи над поставою вдома при дискомфорті в шиї, спині чи плечах від повсякденного навантаження; він не ставить діагноз і не замінює консультацію лікаря. Базове сканування безкоштовне, повний план вправ доступний у Pro-підписці.', 'PhysioAI (AI Posture Therapy) is a mobile app that uses AI to scan your posture and body alignment with the phone camera. Based on the scan it picks personal corrective exercises and builds a home workout plan with step-by-step instructions. The plan can be exported to PDF to print, follow offline or share with a physiotherapist or coach. Repeat scans help you see changes over time. The app suits self-guided posture work at home for everyday neck, back or shoulder discomfort; it does not diagnose and does not replace a doctor''s consultation. The basic scan is free, and the full exercise plan is available with a Pro subscription.', 'AI-сканування постави через камеру
Персональні рекомендації вправ за результатами сканування
План вправ у PDF для друку чи фахівця
Домашні тренування з покроковими інструкціями', 'AI posture scanning with the camera
Personal exercise recommendations based on the scan
PDF exercise plan to print or share with a professional
Home workouts with step-by-step instructions', 'Люди, які хочуть самостійно покращити поставу вдома без візиту до фахівця.', 'People who want to improve their posture on their own at home without visiting a specialist.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-09-30 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apps.apple.com/us/app/ai-posture-therapy-physioai/id6756598601' OR LOWER(`name`) = LOWER('PhysioAI (AI Posture Therapy)')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apps.apple.com/us/app/ai-posture-therapy-physioai/id6756598601' OR LOWER(`name`) = LOWER('PhysioAI (AI Posture Therapy)')) ORDER BY `id` LIMIT 1);
