-- SPRY — Здоров'я та краса › Реабілітація та фізіотерапія
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SPRY', NULL, 'https://www.sprypt.com', NULL, NULL, 'Платформа управління клінікою фізичної терапії: запис і розклад, автоматизація документації, робота зі страховими попередніми погодженнями та аналітика.', 'A practice management platform for physical therapy clinics: scheduling, automated documentation, insurance prior authorisations and analytics.', 'SPRY — комплексна B2B-платформа для клінік фізичної терапії, ерготерапії та реабілітаційних центрів. Вона об''єднує запис пацієнтів і керування розкладом, автоматизацію медичної документації та роботу зі страховими компаніями. Автоматизація попередніх погоджень лікування зі страховиками скорочує затримки перед початком терапії й зменшує ручну адміністративну роботу персоналу. Вбудована аналітика показує ефективність клініки, завантаження фахівців і фінансові показники. Рішення орієнтоване на ринок США, вартість розраховується індивідуально за запитом.', 'SPRY is an all-in-one B2B platform for physical therapy and occupational therapy clinics and rehabilitation centres. It brings together patient booking and schedule management, automated medical documentation and work with insurance companies. Automating treatment prior authorisations with insurers cuts delays before therapy starts and reduces manual admin work for staff. Built-in analytics show clinic performance, clinician utilisation and financial metrics. The solution is aimed at the US market, and pricing is quoted individually on request.', 'Керування записом і розкладом клініки
Автоматизація медичної документації
Робота зі страховими попередніми погодженнями
Аналітика ефективності клініки', 'Clinic booking and schedule management
Automated medical documentation
Insurance prior authorisation handling
Clinic performance analytics', 'Клініки фізичної терапії, ерготерапії та реабілітаційні центри.', 'Physical therapy and occupational therapy clinics and rehabilitation centres.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-09-30 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sprypt.com' OR LOWER(`name`) = LOWER('SPRY')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sprypt.com' OR LOWER(`name`) = LOWER('SPRY')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'health-beauty' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'health-beauty' AND s.`slug` = 'rehabilitation-physiotherapy' LIMIT 1;
