INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'SPRY is an all-in-one B2B platform for physical therapy and occupational therapy clinics and rehabilitation centres. It brings together patient booking and schedule management, automated medical documentation and work with insurance companies. Automating treatment prior authorisations with insurers cuts delays before therapy starts and reduces manual admin work for staff. Built-in analytics show clinic performance, clinician utilisation and financial metrics. The solution is aimed at the US market, and pricing is quoted individually on request.', 'manual' FROM DUAL WHERE @new = 1;
